    if(!old.mapGroup&&old.currentMap){const asset=(state.assets||[]).find(a=>a.id===old.currentMap);const meta=asset?mapMeta(asset):{key:old.currentMap};old.mapGroup=meta.key;old.mapVersion=old.currentMap;old.scenes=old.scenes||{};if(old.scenes[old.currentMap]&&!old.scenes[meta.key])old.scenes[meta.key]=old.scenes[old.currentMap]}
    normalizeSession(old);state.history=state.history||[];state.history.forEach(entry=>entry.snapshot&&normalizeSession(entry.snapshot));
