  async function permission(handle){return(await handle.queryPermission({mode:'read'}))==='granted'||(await handle.requestPermission({mode:'read'}))==='granted'}
  async function boot(){try{migrate(await get('state'));directoryHandle=await get('directoryHandle')||null;if(directoryHandle&&await permission(directoryHandle))await scan(directoryHandle,false)}catch(e){console.warn(e)}initTabletopRenderer();bind();renderAll();if(state.active.updatedAt&&!state.resumed)$('#resume-dialog').showModal();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{})}
  function save(){ $('#save-status').textContent='Salvando…';clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{state.active.updatedAt=new Date().toISOString();try{await set('state',clone(state));$('#save-status').textContent='Salvo neste computador'}catch{ $('#save-status').textContent='Erro ao salvar'}},320)}
  async function pickFolder(){try{if(!window.showDirectoryPicker){alert('Use o Microsoft Edge ou Google Chrome para selecionar a pasta da campanha.');return}directoryHandle=await showDirectoryPicker({mode:'read'});await set('directoryHandle',directoryHandle);await scan(directoryHandle,true)}catch(e){if(e.name!=='AbortError')alert('Não foi possível importar a pasta.')}}
  async function scan(handle,notice){const list=[];files.clear();urls.forEach(URL.revokeObjectURL);urls.clear();async function visit(folder,prefix=''){for await(const entry of folder.values()){const path=prefix?`${prefix}/${entry.name}`:entry.name;if(entry.kind==='directory')await visit(entry,path);else{const cat=category(path),type=typeFor(entry.name);if(cat!=='Outros'&&type!=='arquivo'){const a={id:`asset:${path}`,path,name:entry.name,category:cat,type};list.push(a);files.set(a.id,entry)}}}}await visit(handle);state.assets=list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));state.campaignName=handle.name;ensureCharacters();const available=groups(),current=available.find(g=>g.key===state.active.mapGroup);if(!current&&available[0]){state.active.mapGroup=available[0].key;state.active.mapVersion=available[0].versions[0].id;scene()}else if(current&&!current.versions.some(v=>v.id===state.active.mapVersion))state.active.mapVersion=current.versions[0].id;save();renderAll();if(notice)$('#folder-label').textContent=`${list.length} itens`}
  async function fileFor(id){if(!files.has(id)&&directoryHandle&&await permission(directoryHandle))await scan(directoryHandle,false);return files.get(id)?.getFile()||null}
  async function urlFor(asset){if(!asset)return null;if(urls.has(asset.id))return urls.get(asset.id);const file=await fileFor(asset.id);if(!file)return null;const url=URL.createObjectURL(file);urls.set(asset.id,url);return url}
  function characterName(token){return stem(token.name).replace(/^personagem\s*-\s*/i,'').trim()}
  function isFigure(token){return /^personagem\s*-/i.test(token?.name||'')}
  function sheetRecordKey(character){const sheet=asset(character.sheetId),sheetName=sheet&&stem(sheet.name).replace(/^ficha\s*-\s*/i,'');return norm(sheetName||character.name)}
  function recordFor(character){return SHEET_RECORDS[sheetRecordKey(character)]||null}
  function baselineFor(character){return SHEET_BASELINES[sheetRecordKey(character)]||null}
  function applySheetRecord(character){const record=recordFor(character);if(!record)return false;character.sheetData=clone(record);return true}
  function applySheetBaseline(character,force=false){const baseline=baselineFor(character);if(!baseline)return false;let changed=false;[['hp',baseline.hp],['pd',baseline.pd]].forEach(([field,value])=>{const raw=String(character[field]||'').trim(),parsed=track(raw);if(force||!raw){character[field]=`${value}/${value}`;changed=true;return}if(parsed&&parsed.max===null){character[field]=`${Math.max(0,Math.min(value,parsed.current))}/${value}`;changed=true}});if(changed)character.statusSource='ficha';return changed}
  function standeePresentation(character){const fallback=character.size||48,defaults={mode:character.fullBody?'STANDEE':'TOKEN',scale:fallback,footAnchorX:.5,footAnchorY:1,shadowWidth:.62,shadowHeight:.14,verticalOffset:0,baseDiameter:.9,baseThickness:.2,supportWidth:.28,supportHeight:.34,contactShadow:.76,material:'obsidian-metal'};if(!character.presentation)character.presentation={...defaults};else Object.entries(defaults).forEach(([key,value])=>{if(character.presentation[key]===undefined)character.presentation[key]=value});if(character.fullBody&&norm(character.name)==='alan'&&character.presentation.mode==='STANDEE')character.presentation.mode='TABLETOP_FIGURE';return character.presentation}
  function matchSheet(token){const base=norm(characterName(token));let best=null,score=0;state.assets.filter(a=>a.category==='Fichas').forEach(sheet=>{const candidate=norm(stem(sheet.name));const value=candidate===base?3:(candidate.includes(base)||base.includes(candidate)?2:0);if(value>score){best=sheet;score=value}});return best?.id||''}
  function ensureCharacters(){const all=state.assets.filter(a=>a.category==='Tokens'&&a.type==='imagem'),figures=all.filter(isFigure),sources=figures.length?figures:all;const figureByName=new Map(figures.map(token=>[norm(characterName(token)),`char:${token.id}`]));Object.entries(state.characters).forEach(([oldId,old])=>{const oldAsset=asset(old.tokenId);if(oldAsset&&!isFigure(oldAsset)){const replacement=figureByName.get(norm(old.name.replace(/^token\s*-\s*/i,'')));if(replacement){Object.values(state.active.scenes||{}).forEach(scene=>scene.markers?.forEach(marker=>{if(marker.characterId===oldId)marker.characterId=replacement}));delete state.characters[oldId]}}});sources.forEach(token=>{const id=`char:${token.id}`,name=characterName(token);if(!state.characters[id]){const character={id,tokenId:token.id,name,sheetId:matchSheet(token),hp:'',pd:'',sanity:'',defense:'',conditions:'',notes:'',size:48,fullBody:isFigure(token)};applySheetRecord(character);applySheetBaseline(character);state.characters[id]=character}else{const character=state.characters[id];if(character.pd===undefined)character.pd=character.pe||'';if(!character.sheetId)character.sheetId=matchSheet(token);applySheetRecord(character);applySheetBaseline(character);if(isFigure(token))character.fullBody=true}});Object.values(state.characters).filter(character=>character.fullBody).forEach(standeePresentation);if(!state.active.participantsConfigured&&Object.keys(state.characters).length){state.active.activeCharacterIds=Object.keys(state.characters);state.active.participantsConfigured=true}}
  function groups(){const map=new Map();state.assets.filter(a=>a.category==='Mapas'&&a.type==='imagem').forEach(asset=>{const meta=mapMeta(asset);if(!map.has(meta.key))map.set(meta.key,{...meta,versions:[]});map.get(meta.key).versions.push({...asset,version:meta.version})});return[...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'))}
  function activeGroup(){return groups().find(g=>g.key===state.active.mapGroup)}
  function scene(){const key=state.active.mapGroup;if(!key)return null;return state.active.scenes[key]||(state.active.scenes[key]={panX:0,panY:0,scale:1,viewInitialized:false,markers:[],strokes:[],gmNarration:'',tableCamera:{targetX:0,targetZ:0,distance:18,yaw:.62,pitch:.82,fov:.72}})}
  const isActiveCharacter = id => state.active.activeCharacterIds.includes(id);
  function moveTokenPreview(x,y){const preview=$('#token-drag-preview');if(!preview)return;preview.style.left=`${x}px`;preview.style.top=`${y}px`}
  function showTokenPreview(markerId,x,y){const marker=scene()?.markers.find(item=>item.id===markerId),character=marker&&state.characters[marker.characterId],preview=$('#token-drag-preview');if(!character||!preview)return;preview.dataset.markerId=markerId;preview.hidden=false;preview.querySelector('b').textContent=character.name;moveTokenPreview(x,y);urlFor(characterPortrait(character)).then(url=>{if(url&&preview.dataset.markerId===markerId)preview.querySelector('img').src=url})}
  function hideTokenPreview(markerId){const preview=$('#token-drag-preview');if(!preview||preview.dataset.markerId!==markerId)return;preview.hidden=true;preview.dataset.markerId=''}
  function initTabletopRenderer(){const canvas=$('#tabletop-canvas');if(!canvas||!window.TabletopRenderer)return;tabletopRenderer=new window.TabletopRenderer(canvas,{onSelect:markerId=>{const marker=scene()?.markers.find(item=>item.id===markerId);if(marker?.characterId)selectCharacter(marker.characterId)},onTokenMove:(markerId,point)=>{const marker=scene()?.markers.find(item=>item.id===markerId);if(marker){marker.x=point.x;marker.y=point.y}},onTokenDragStart:showTokenPreview,onTokenDrag:(markerId,x,y)=>moveTokenPreview(x,y),onTokenDragEnd:hideTokenPreview,onCameraChange:camera=>{const current=scene();if(current){current.tableCamera=camera;save()}},onInteractionEnd:()=>save(),shouldPlace:()=>state.mapTool==='place'&&Boolean(state.selectedCharacter)&&isActiveCharacter(state.selectedCharacter),onPlace:point=>addCharacterMarker(state.selectedCharacter,null,null,false,point),onError:message=>console.warn(message)});if(!tabletopRenderer.ready){tabletopRenderer=null;return}const drawTool=$('.tool[data-tool="draw"]'),genericMarker=$('#add-marker');if(drawTool){drawTool.disabled=true;drawTool.title='Desenhos serão migrados para o tabuleiro 3D em uma fase posterior'}if(genericMarker){genericMarker.disabled=true;genericMarker.title='Marcadores genéricos serão migrados para o tabuleiro 3D em uma fase posterior'}}
  function bind(){
    $$('.choose-folder').forEach(b=>b.addEventListener('click',pickFolder));$('#map-group').addEventListener('change',e=>changeGroup(e.target.value));$('#map-version').addEventListener('change',e=>changeVersion(e.target.value));
    $$('.tool[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));$('#add-marker').addEventListener('click',()=>addMarker());$('#focus-character').addEventListener('click',focusSelectedCharacter);$('#zoom-in').addEventListener('click',()=>zoom(.15));$('#zoom-out').addEventListener('click',()=>zoom(-.15));$('#zoom-reset').addEventListener('click',resetZoom);document.addEventListener('keydown',tabletopKeydown);
    $('#map-shell').addEventListener('dragover',e=>e.preventDefault());$('#map-shell').addEventListener('drop',e=>{e.preventDefault();const id=e.dataTransfer.getData('character');if(id)addCharacterMarker(id,e.clientX,e.clientY,false)});$('#map-shell').addEventListener('wheel',mapWheel,{passive:false});$('#map-shell').addEventListener('pointerdown',mapPointerDown);
    $$('.panel-tab').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));$('#close-panel').addEventListener('click',closePanel);
    $$('.dice-choice').forEach(button=>button.addEventListener('click',()=>addSelectedDie(+button.dataset.dice)));$('#roll-selected').addEventListener('click',rollSelectedDice);$('#clear-dice').addEventListener('click',clearSelectedDice);$('#custom-roll').addEventListener('submit',e=>{e.preventDefault();roll(+$('#dice-quantity').value,+$('#dice-sides').value,+$('#dice-modifier').value,e.submitter)});renderDiceSelection();
    $('#resume-dialog').addEventListener('close',()=>{$('#resume-dialog').returnValue==='confirm'?(state.resumed=true,renderAll()):newSession()});$('#end-form').addEventListener('submit',endSession);$('#cancel-end').addEventListener('click',()=>$('#end-dialog').close());
  }
  function renderAll(){ensureCharacters();$('#campaign-import').hidden=Boolean(state.campaignName&&state.assets.length);renderMapPicker();renderMap();renderCharacters();if(state.openPanel)renderPanel(state.openPanel)}
  function renderMapPicker(){const gs=groups(),group=$('#map-group'),version=$('#map-version');group.innerHTML='<option value="">Escolha um mapa</option>'+gs.map(g=>`<option value="${esc(g.key)}">${esc(g.name)}</option>`).join('');group.value=state.active.mapGroup||'';const current=activeGroup();version.disabled=!current;version.innerHTML=current?current.versions.map(v=>`<option value="${esc(v.id)}">${esc(v.version)}</option>`).join(''):'<option>Versão</option>';if(current){if(!current.versions.some(v=>v.id===state.active.mapVersion))state.active.mapVersion=current.versions[0].id;version.value=state.active.mapVersion}}
  function changeGroup(key){state.active.mapGroup=key||null;const group=activeGroup();state.active.mapVersion=group?.versions[0]?.id||null;if(group)scene();save();renderMapPicker();renderMap()}
  function changeVersion(id){state.active.mapVersion=id;save();renderMap()}
  async function renderMap(){const group=activeGroup(),asset=group?.versions.find(v=>v.id===state.active.mapVersion),empty=$('#map-empty'),stage=$('#map-stage'),canvas=$('#tabletop-canvas');if(!asset){empty.hidden=false;stage.hidden=true;canvas.hidden=true;return}const url=await urlFor(asset);if(!url){empty.hidden=false;empty.innerHTML='<span>!</span><h1>Reconecte a campanha</h1><p>O arquivo do mapa não está acessível.</p>';stage.hidden=true;canvas.hidden=true;return}if(!tabletopRenderer){empty.hidden=false;empty.innerHTML='<span>!</span><h1>Visualização 3D indisponível</h1><p>Não foi possível iniciar o renderizador do tabuleiro.</p>';stage.hidden=true;canvas.hidden=true;return}empty.hidden=true;canvas.hidden=false;stage.hidden=true;const image=$('#map-image');image.onload=async()=>{stage.style.width=`${image.naturalWidth}px`;stage.style.height=`${image.naturalHeight}px`;const c=$('#draw-canvas');c.width=image.naturalWidth;c.height=image.naturalHeight;c.style.width=`${image.naturalWidth}px`;c.style.height=`${image.naturalHeight}px`;tabletopRenderer.setState(scene());const rendered=await tabletopRenderer.setMap(url,image);if(rendered){syncTabletopRenderer();return}canvas.hidden=true;empty.hidden=false;empty.innerHTML='<span>!</span><h1>Não foi possível renderizar o mapa 3D</h1><p>Tente selecionar a cena novamente.</p>'};image.onerror=()=>{canvas.hidden=true;stage.hidden=true;empty.hidden=false;empty.innerHTML='<span>!</span><h1>Não foi possível carregar o mapa</h1><p>Tente selecionar a cena novamente.</p>'};image.src=url;tabletopRenderer.setState(scene())}
  function paintScene(){const s=scene();if(!s)return;if(tabletopRenderer){tabletopRenderer.setState(s);$('#zoom-reset').textContent='3D';syncTabletopRenderer();return}const stage=$('#map-stage');stage.style.left=`calc(50% + ${s.panX}px)`;stage.style.top=`calc(50% + ${s.panY}px)`;stage.style.transform=`translate(-50%,-50%) scale(${s.scale})`;$('#zoom-reset').textContent=`${Math.round(s.scale*100)}%`;drawStrokes();renderMarkers()}
  function drawStrokes(){const s=scene(),canvas=$('#draw-canvas');if(!s||!canvas.width)return;const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.lineCap='round';c.lineJoin='round';s.strokes.forEach(stroke=>{if(stroke.points.length<2)return;c.strokeStyle=stroke.color;c.lineWidth=stroke.width;c.beginPath();stroke.points.forEach((p,i)=>i?c.lineTo(p.x*canvas.width,p.y*canvas.height):c.moveTo(p.x*canvas.width,p.y*canvas.height));c.stroke()})}
  function pos(x,y){if(tabletopRenderer)return tabletopRenderer.screenToBoard(x,y)||{x:.5,y:.5};const r=$('#map-stage').getBoundingClientRect();return{x:Math.max(0,Math.min(1,(x-r.left)/r.width)),y:Math.max(0,Math.min(1,(y-r.top)/r.height))}}
